const e = $json.body.event ?? $json.body;
const type = e.type;                       // INITIAL_PURCHASE | RENEWAL | TRANSFER | ...
const appUserId = e.app_user_id;
const ent = (e.entitlement_ids && e.entitlement_ids[0]) || '';
const planByEnt = { tier_start: 'start', tier_business: 'business', tier_network: 'network' };
const out = { app_user_id: appUserId, topup_delta: 0 };
const ids = (a) => (Array.isArray(a) ? a.filter((x) => typeof x === 'string' && x.length > 0) : []);

if (type === 'TRANSFER') {
  // TRANSFER несёт ТОЛЬКО transferred_from/transferred_to (в доках RC — String arrays,
  // «App User ID(s)»); ни app_user_id, ни product_id, ни entitlement_ids в нём НЕТ.
  // Это МЕЖАККАУНТНЫЙ переезд. Переустановку на том же устройстве RC шлёт НЕ так — см. ниже.
  const from = ids(e.transferred_from);
  const to = ids(e.transferred_to);
  if (!from.length || !to.length) return [{ json: out }];   // пустые массивы -> no-op (Respond No-Op)
  return [{ json: { app_user_id: '', topup_delta: 0, to_ids: JSON.stringify(to), from_ids: JSON.stringify(from) } }];
}

// СКЛЕЙКА ИДЕНТИЧНОСТЕЙ (alias-merge). При переустановке RC НЕ шлёт TRANSFER: событие
// приходит под НОВЫМ app_user_id, а старый лежит в original_app_user_id и в aliases[]
// (живые события 3150/3151/3153 от 2026-08-26; transferred_* там null). Доки RC прямо
// говорят искать «both the original_app_user_id and the aliases array». Алиасы едут на
// КАЖДОМ событии всегда, поэтому alias_ids выставляется только когда есть что сводить —
// иначе If-гейт ниже экономит целый round-trip в Postgres.
const cur = typeof appUserId === 'string' ? appUserId : '';
const aliasIds = [...new Set([
  ...ids(e.aliases),
  ...(typeof e.original_app_user_id === 'string' ? [e.original_app_user_id] : []),
].filter((x) => x && x !== cur))];
if (cur && aliasIds.length) out.alias_ids = JSON.stringify(aliasIds);

if (type === 'NON_RENEWING_PURCHASE' && e.product_id === 'topup.dialogs.500') {
  out.topup_delta = 500;                   // план/статус/product_id не трогаем
} else if (['INITIAL_PURCHASE','RENEWAL','UNCANCELLATION','PRODUCT_CHANGE'].includes(type)) {
  out.plan = planByEnt[ent] ?? 'none';
  out.status = 'active';
  out.period_end = e.expiration_at_ms ? new Date(e.expiration_at_ms).toISOString() : null;
  // PRODUCT_CHANGE несёт СТАРЫЙ sku в product_id, а новый — в new_product_id (доки RC;
  // живое наблюдение 2026-08-26, exec 3128: product_id=sub.start.month при апгрейде на
  // sub.business.month). `??` выбран НАМЕРЕННО: он одинаково обрабатывает и отсутствие
  // ключа, и явный null — не менять на `'new_product_id' in e`. На этом инстансе все 34
  // реальные доставки несли этот ключ только у PRODUCT_CHANGE, но доки описывают его как
  // «omitted when null», а не «никогда не приходит null».
  out.product_id = e.new_product_id ?? e.product_id ?? null;   // .month/.year суффикс SKU -> интервал в Get Usage
} else if (type === 'EXPIRATION') {
  out.status = 'expired';
} else if (type === 'CANCELLATION') {
  return [];                               // автопродление выключили — доступ до period_end, ничего не меняем
}
return [{ json: out }];
